fn is_palindrome(text: Vec<char>) -> bool {
    let mut left = 0;
    let mut right = text.len().saturating_sub(1); // Avoid underflow for empty vector

    while left < right {
        let left_char = text[left];
        let right_char = text[right];

        // Convert to lowercase if it's an uppercase letter
        let left_lower = if left_char.is_ascii_uppercase() {
            (left_char as u8 + 32) as char // Convert to lowercase
        } else {
            left_char
        };

        let right_lower = if right_char.is_ascii_uppercase() {
            (right_char as u8 + 32) as char // Convert to lowercase
        } else {
            right_char
        };

        if left_lower != right_lower {
            return false; // Not a palindrome
        }

        left += 1;
        right -= 1;
    }

    true // It is a palindrome
}